import socket, struct
def dns_query(name, server, qtype=1, timeout=3):
    header=struct.pack(">HHHHHH", 0x1234, 0x0100, 1, 0, 0, 0)
    qname=b"".join(bytes([len(p)])+p.encode() for p in name.split("."))+b"\x00"
    q=header+qname+struct.pack(">HH",qtype,1)
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(timeout)
    s.sendto(q,(server,53))
    data,_=s.recvfrom(2048)
    return data[3]&0xf, struct.unpack(">H",data[6:8])[0], data
for server in ["192.168.65.7","8.8.8.8"]:
    for n in ["prices.internal","prices.internal.corp-62d50cb4","google.com"]:
        try:
            rcode, an, d = dns_query(n, server)
            print(server, n, "rcode",rcode,"an",an, d[-80:] if rcode!=0 else "")
        except Exception as e:
            print(server, n, "err", e)
EOF"}

